  ('5EG5','Gap filling','Complete the sentence: ___ the vegetables before adding them to the soup.','[{"id":"a","text":"Wash"},{"id":"b","text":"Washes"},{"id":"c","text":"Washing"},{"id":"d","text":"To wash"}]'::jsonb,'"a"'::jsonb,'An affirmative imperative begins with the base form of a verb.','Read the whole sentence, identify the grammar pattern and then compare all four options.',2),
  ('5EG5','Sentence use','Which sentence is grammatically correct? (Set 1)','[{"id":"a","text":"Washes the vegetables before adding them to the soup."},{"id":"b","text":"Washing the vegetables before adding them to the soup."},{"id":"c","text":"To wash the vegetables before adding them to the soup."},{"id":"d","text":"Wash the vegetables before adding them to the soup."}]'::jsonb,'"d"'::jsonb,'An affirmative imperative begins with the base form of a verb.','Read the whole sentence, identify the grammar pattern and then compare all four options.',3),
  ('5EG5','Grammar rule','Which rule best explains the answer in this example: “Wash the vegetables before adding them to the soup.”?','[{"id":"a","text":"A modal verb must always be followed by to."},{"id":"b","text":"Use has with all plural subjects."},{"id":"c","text":"An affirmative imperative begins with the base form of a verb."},{"id":"d","text":"Use an adjective after every action verb."}]'::jsonb,'"c"'::jsonb,'An affirmative imperative begins with the base form of a verb.','Read the whole sentence, identify the grammar pattern and then compare all four options.',3),
